const observer = new MutationObserver(mutations => {
  console.log(mutations);
});

btn1.addEventListener('click', () => {
  observer.observe(text1, {
    characterData: true,
    subtree: true
  });
});
btn2.addEventListener('click', () => {
  observer.observe(text2, {
    characterData: true,
    subtree: true
  });
});
stopBtn.addEventListener('click', () => {
  observer.disconnect();
});
